categories = []
def cat(cid, title, description, mode="open"):
    c = {"id": cid, "title": title, "description": description, "default_mode": mode, "questions": []}
    categories.append(c)
    return c

def q(c, value, prompt, answer, accept, explain, sources, *, image=None, options=None, note="", crop=None):
    item = {"id": f"q{c['id']:02d}-{value}", "value": value, "prompt": prompt, "answer": answer,
            "accepted_answers": accept, "explanation": explain, "source_ids": sources,
            "time_seconds": 30 if value >= 400 else 20, "host_note": note,
            "editorial_status": "ready_for_host_review", "options": options or [], "media": None}
    if image:
        a = assets[image]
        item["media"] = {"kind": "image", "path": a["path"], "source_id": image,
                         "question_alt": "Изображение к вопросу " + item["id"],
                         "answer_alt": answer, "question_crop_normalized": crop,
                         "reveal": "full_original", "crop_implementation": "display-only viewport; original file retained"}
    c["questions"].append(item)

