pack={"title":"Своя компания — пакет 01", "version":"1.0-editorial", "prepared_at":"2026-11-07",
      "language":"ru", "players":{"min":6,"max":7,"mode":"individual"},
      "target_minutes":[60,90], "format":"category_board_100_500", "categories":categories,
      "sources":{k:{"title":v[0],"url":v[1],"checked_at":"2026-11-07"} for k,v in S.items()},
      "rounds":[{"id":1,"category_ids":[1,2,4,5,8]},{"id":2,"category_ids":[3,6,7,9,10]}],
      "notes":["Пакет содержит ровно 50 вопросов: 10 категорий по 100–500.",
               "Все шуточные формулировки авторские, если явно не указана короткая публичная реплика.",
               "Вопросы здесь не требуют настоящего опроса аудитории; статистика «100 к 1» не выдумывалась.",
               "Цены — предварительная редакторская оценка. У бинарных вопросов цена отражает неоднозначность кадра, а не объём знаний.",
               "Пять прямоугольников кадрирования заданы как x,y,width,height от 0 до 1; это параметры будущего показа, а не отредактированные изображения."]}

(ROOT/"quiz-pack.json").write_text(json.dumps(pack,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")

md=["# Своя компания — пакет 01", "", "**Для ведущего. Здесь есть все ответы и раскрытия. Игрокам файл не показывать.**", "",
    "Подготовлено 7 ноября 2026 года. 6–7 игроков, каждый за себя. 10 категорий × 5 вопросов = 50 вопросов по 100, 200, 300, 400 и 500 баллов.", "",
    "Два раунда по 25 вопросов. Ориентир: 30–35 минут на раунд, 5 минут на правила, 5 минут на перерыв и запас на обсуждения — примерно 70–90 минут. Чтобы уложиться в час, ограничить обсуждение после раскрытия. Стоимость во втором раунде остаётся 100–500.", "",
    "Обычные вопросы: 20–30 секунд на размышление, ведущий фиксирует ответ и вручную выдаёт баллы. Для 6–7 человек удобно давать выбравшему первый ответ, затем одну попытку перехвата остальным. На визуальной категории №9 все одновременно показывают условный знак или записывают один из двух вариантов: верный ответ приносит стоимость каждому угадавшему. Это убирает преимущество самых громких.", "",
    "Варианты ответа, если они есть, составляют часть вопроса: их читать сразу. Близкие по смыслу ответы принимать по указанным критериям. За ошибку предлагаю не снимать баллы: вечер дружеский, а дорогие вопросы должны провоцировать версии.", "",
    "Тексты юмористических описаний написаны специально для этой игры. Фактическая основа и происхождение фотографий указаны у вопросов. Это редакторская версия для вашего просмотра; сложность надо оценивать по вашей компании.", "",
    "## Поле", "", "| № | Категория | Формат |", "|---|---|---|"]
for c in categories:
    fmt="Фрагмент → полный кадр" if c['id']==9 else "Фото предмета" if c['id']==8 else "Текст + фото" if c['id']==4 else "Текст"
    md.append(f"| {c['id']} | {c['title']} | {fmt} |")
for c in categories:
    md += ["",f"## {c['id']}. {c['title']}","",c['description'],""]
    for item in c['questions']:
        md += [f"### {item['value']} баллов — {item['id']}","",item['prompt'],""]
        if item['options']:
            md += ["Варианты: "+" / ".join(item['options'])+".",""]
        if item['media']:
            im=item['media']
            md += [f"Изображение: [{Path(im['path']).name}]({(ROOT/im['path']).as_posix()}).",""]
            if im['question_crop_normalized']:
                md += ["Показ вопроса: только лицо в указанном в JSON прямоугольнике. Раскрытие: полный оригинал. Границы заданы по просмотренным оригиналам; окончательную видимость проверим при создании сайта.",""]
        md += [f"**Ответ:** {item['answer']}.","",f"**Зачёт:** {'; '.join(item['accepted_answers'])}.","",item['explanation'],""]
        if item['host_note']:
            md += ["**Ведущему:** "+item['host_note'],""]
        links=[f"[{S[k][0]}]({S[k][1]})" for k in item['source_ids']]
        if item['media']:
            a=assets[item['media']['source_id']]
            links.append(f"[Происхождение изображения]({a['source_url']})")
        md += ["Источники: "+"; ".join(links)+".",""]
(ROOT/"ВИКТОРИНА_50_ВОПРОСОВ.md").write_text("\n".join(md),encoding="utf-8")

credits=["# Источники изображений", "", "Оригиналы сохранены без редактирования. Имена нейтральные, чтобы не выдавать ответ. Параметры кадрирования хранятся в quiz-pack.json; на данном этапе это инструкция будущему показу.", ""]
for a in assets.values():
    strip=lambda x: re.sub('<[^>]+>','',x or '').strip()
    credits += [f"## {a['id']}", "", f"Файл: `{a['path']}`", "", f"Источник: [{a['title']}]({a['source_url']})", "",
                f"Автор / организация: {strip(a['author_html'])}", "", f"Лицензия по карточке: {a['license']}", ""]
    if a.get('license_url'): credits += [f"[Условия лицензии]({a['license_url']})", ""]
    if a.get('publication_review'): credits += ["Перед открытой публикацией: для снимка Джейн Фонды на исходной странице не указана лицензия повторного использования; требуется проверить права или подобрать замену. Для локальной подготовки оригинал сохранён.", ""]
(ROOT/"assets/ИСТОЧНИКИ_ИЗОБРАЖЕНИЙ.md").write_text("\n".join(credits),encoding="utf-8")

assert len(categories)==10
assert sum(len(c['questions']) for c in categories)==50
for c in categories:
    assert [x['value'] for x in c['questions']]==[100,200,300,400,500]
    for x in c['questions']:
        assert x['answer'] and x['source_ids']
        assert all(s in S for s in x['source_ids'])
        if x['media']:
            assert (ROOT/x['media']['path']).exists()
            if x['media']['question_crop_normalized']:
                a,b,w,h=x['media']['question_crop_normalized']
                assert min(a,b,w,h)>=0 and a+w<=1 and b+h<=1
print(f"Готово: {len(categories)} категорий, 50 вопросов, {sum(x['media'] is not None for c in categories for x in c['questions'])} вопросов с изображениями.")
